import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useLenis } from "lenis/react";
import { UserRound } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthDialog } from "../auth/AuthDialog";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import { useAccountStore } from "../../lib/auth";
import { LandingBook } from "./LandingBook";
import {
  EnterAct,
  CraftAct,
  HeroAct,
  NumbersAct,
  StoryAct,
} from "./LandingSections";
import { LANDING_ACTS, NAV_LINKS } from "./landingContent";
import { prefetchHomeLobby } from "../../lib/routePrefetch";
import "./landing-page.css";

gsap.registerPlugin(ScrollTrigger);

/** The product introduction always hands the reader back to the bookshelf. */
export const LIBRARY_PATH = "/shelf";

/**
 * The floating book's pose in each act. The page lerps between the pose of
 * the act you are looking at and the next one, so the book never stops
 * turning — it is the through-line that makes six separate sections read as
 * one continuous room.
 */
type BookPose = {
  /** rotateY, degrees */
  ry: number;
  /** rotateX, degrees */
  rx: number;
  /** uniform scale */
  sc: number;
  /** horizontal nudge of the whole stage, in vw */
  dx: number;
  /** vertical nudge of the whole stage, in vh */
  dy: number;
  /** Opacity of the book itself. Only the mobile layout reads it (through
   *  --bk-alpha in landing-page.css): there the hero's copy ends above the
   *  book's empty band, so the book rides at full strength, while every
   *  other act shares its viewport with copy and keeps it a watermark.
   *  Desktop ignores the value and always draws the book at full strength. */
  alpha: number;
};

const BOOK_POSES: Record<string, BookPose> = {
  hero: { ry: -26, rx: 7, sc: 1, dx: 7, dy: 0, alpha: 1 },
  story: { ry: 30, rx: -3, sc: 0.86, dx: -1, dy: -2, alpha: 0.18 },
  craft: { ry: -14, rx: 10, sc: 0.84, dx: 0, dy: 0, alpha: 0.18 },
  numbers: { ry: -32, rx: 3, sc: 0.88, dx: -4, dy: -2, alpha: 0.18 },
  enter: { ry: 20, rx: 2, sc: 0.96, dx: 6, dy: -1, alpha: 0.18 },
};

const FALLBACK_POSE: BookPose = BOOK_POSES.hero!;

type Keyframe = { p: number; pose: BookPose; act: string };

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

const lerp = (from: number, to: number, t: number) => from + (to - from) * t;

const lerpPose = (a: BookPose, b: BookPose, t: number): BookPose => ({
  ry: lerp(a.ry, b.ry, t),
  rx: lerp(a.rx, b.rx, t),
  sc: lerp(a.sc, b.sc, t),
  dx: lerp(a.dx, b.dx, t),
  dy: lerp(a.dy, b.dy, t),
  alpha: lerp(a.alpha, b.alpha, t),
});

/**
 * The landing route.
 *
 * Flow: the hero plays its entrance immediately and the scroll choreography
 * arms. Nothing auto-navigates: the final act and the nav both run the same
 * door wipe before the router moves to the knowledge library.
 */
export function LandingPage() {
  const navigate = useNavigate();
  const lenis = useLenis();
  const prefersReducedMotion = usePrefersReducedMotion();
  const session = useAccountStore((state) => state.session);

  const rootRef = useRef<HTMLDivElement>(null);
  const flowRef = useRef<HTMLElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const doorRef = useRef<HTMLDivElement>(null);
  const railRef = useRef<HTMLOListElement>(null);

  const [entering, setEntering] = useState(false);
  const [activeAct, setActiveAct] = useState("hero");
  const [accountOpen, setAccountOpen] = useState(false);

  const keyframesRef = useRef<Keyframe[]>([]);
  const progressRef = useRef(0);
  const activeRef = useRef("hero");

  const tone = useMemo(
    () => LANDING_ACTS.find((act) => act.id === activeAct)?.tone ?? "dawn",
    [activeAct],
  );

  /** Writes one pose onto the fixed stage. Only custom properties move, so
   *  the browser keeps the whole 3D box on one composited layer. */
  const applyPose = useCallback((pose: BookPose) => {
    const stage = stageRef.current;
    if (!stage) return;
    stage.style.setProperty("--bk-ry", `${pose.ry.toFixed(3)}deg`);
    stage.style.setProperty("--bk-rx", `${pose.rx.toFixed(3)}deg`);
    stage.style.setProperty("--bk-sc", pose.sc.toFixed(4));
    stage.style.setProperty("--bk-dx", `${pose.dx.toFixed(3)}vw`);
    stage.style.setProperty("--bk-dy", `${pose.dy.toFixed(3)}vh`);
    stage.style.setProperty("--bk-alpha", pose.alpha.toFixed(3));
  }, []);

  /** Reads the scroll progress out of the ref and paints the frame. Called
   *  from the ScrollTrigger's onUpdate, so it is already raf-aligned. */
  const paint = useCallback(() => {
    const frames = keyframesRef.current;
    if (!frames.length) return;
    const p = progressRef.current;

    let index = 0;
    while (index < frames.length - 2 && frames[index + 1]!.p < p) index += 1;
    const from = frames[index]!;
    const to = frames[index + 1] ?? from;
    const span = Math.max(to.p - from.p, 1e-6);
    const raw = clamp((p - from.p) / span, 0, 1);
    // Smoothstep: the book settles into each pose instead of ticking between
    // them, which is what makes the turn feel weighted.
    applyPose(lerpPose(from.pose, to.pose, raw * raw * (3 - 2 * raw)));

    const next =
      frames.find((frame, i) => {
        const end = frames[i + 1]?.p ?? 1;
        return p >= frame.p && p < end;
      })?.act ??
      frames[frames.length - 1]!.act;

    if (next !== activeRef.current) {
      activeRef.current = next;
      setActiveAct(next);
    }
  }, [applyPose]);

  /** Measures the acts and rebuilds the keyframe track. Runs on mount, on
   *  refresh and whenever the flow reflows (fonts landing, covers loading). */
  const measure = useCallback(() => {
    const flow = flowRef.current;
    if (!flow) return;
    const sections = Array.from(
      flow.querySelectorAll<HTMLElement>("[data-landing-section]"),
    );
    const scrollable = Math.max(flow.offsetHeight - window.innerHeight, 1);

    const frames: Keyframe[] = [{ p: 0, pose: FALLBACK_POSE, act: "hero" }];
    sections.forEach((section) => {
      const center =
        section.offsetTop + section.offsetHeight / 2 - window.innerHeight / 2;
      frames.push({
        p: clamp(center / scrollable, 0, 1),
        pose: BOOK_POSES[section.dataset.act ?? ""] ?? FALLBACK_POSE,
        act: section.dataset.act ?? "hero",
      });
    });
    frames.push({
      p: 1,
      pose: BOOK_POSES.enter ?? FALLBACK_POSE,
      act: "enter",
    });

    // Keep the track strictly increasing: acts shorter than a viewport can
    // otherwise collapse onto the same progress value and produce a division
    // by a zero-length span.
    const sorted = frames.sort((a, b) => a.p - b.p);
    const deduped: Keyframe[] = [];
    sorted.forEach((frame) => {
      const last = deduped[deduped.length - 1];
      if (last && frame.p - last.p < 1e-4) return;
      deduped.push(frame);
    });
    keyframesRef.current = deduped;
    paint();
  }, [paint]);

  // The hero entrance. It is a separate effect from the scroll work because
  // it is the only part of the choreography that is time-driven rather than
  // scroll-driven.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    if (prefersReducedMotion) {
      gsap.set(root.querySelectorAll("[data-reveal]"), { clearProps: "all" });
      return undefined;
    }

    const hero = root.querySelector<HTMLElement>('[data-act="hero"]');
    if (!hero) return undefined;

    const context = gsap.context(() => {
      const timeline = gsap.timeline({ defaults: { ease: "power3.out" } });
      const rise = (selector: string, at: number) =>
        timeline.fromTo(
          hero.querySelectorAll(selector),
          { autoAlpha: 0, y: 26 },
          { autoAlpha: 1, y: 0, duration: 0.72, stagger: 0.07 },
          at,
        );

      rise(".landing-act__eyebrow", 0);
      timeline.fromTo(
        hero.querySelectorAll('.landing-mask__glyph[data-reveal="mask"]'),
        { yPercent: 118, rotate: 2.6 },
        {
          yPercent: 0,
          rotate: 0,
          duration: 0.94,
          stagger: 0.09,
          ease: "power4.out",
        },
        0.12,
      );
      timeline.fromTo(
        hero.querySelectorAll('[data-reveal="rule"]'),
        { scaleX: 0 },
        { scaleX: 1, duration: 0.7, transformOrigin: "left center" },
        0.58,
      );
      rise('[data-reveal="rise"]', 0.62);
      timeline.fromTo(
        hero.querySelectorAll(".landing-hero__stamp"),
        { autoAlpha: 0, scale: 0.7, rotate: -40 },
        { autoAlpha: 1, scale: 1, rotate: 0, duration: 1.1, ease: "back.out(1.4)" },
        0.5,
      );
      timeline.fromTo(
        hero.querySelectorAll(".landing-hero__aside"),
        { autoAlpha: 0, x: 18 },
        { autoAlpha: 1, x: 0, duration: 0.7 },
        0.78,
      );
      timeline.fromTo(
        stageRef.current,
        { autoAlpha: 0, scale: 0.86, y: 42 },
        { autoAlpha: 1, scale: 1, y: 0, duration: 1.25, ease: "power3.out" },
        0.22,
      );
    }, root);

    return () => context.revert();
  }, [prefersReducedMotion]);

  // Scroll choreography.
  useEffect(() => {
    const root = rootRef.current;
    const flow = flowRef.current;
    if (!root || !flow) return undefined;

    const context = gsap.context(() => {
      if (prefersReducedMotion) {
        // Static page: park the book in its hero pose and show everything.
        applyPose(FALLBACK_POSE);
        gsap.set(root.querySelectorAll("[data-reveal]"), { clearProps: "all" });
        return;
      }

      measure();
      ScrollTrigger.create({
        trigger: flow,
        start: "top top",
        end: "bottom bottom",
        onUpdate: (self) => {
          progressRef.current = self.progress;
          paint();
        },
        onRefresh: measure,
      });

      // Reveals. The hero is already on screen, so it is excluded here and
      // driven by the entrance timeline instead.
      root
        .querySelectorAll<HTMLElement>('[data-landing-section]:not([data-act="hero"])')
        .forEach((section) => {
          const targets = Array.from(
            section.querySelectorAll<HTMLElement>("[data-reveal]"),
          );
          if (!targets.length) return;

          const masks = targets.filter(
            (target) => target.dataset.reveal === "mask",
          );
          const rests = targets.filter(
            (target) => target.dataset.reveal !== "mask",
          );

          const timeline = gsap.timeline({
            scrollTrigger: {
              trigger: section,
              start: "top 74%",
              once: true,
            },
          });

          if (masks.length) {
            timeline.fromTo(
              masks,
              { yPercent: 118, rotate: 2.6 },
              {
                yPercent: 0,
                rotate: 0,
                duration: 0.9,
                stagger: 0.08,
                ease: "power4.out",
              },
              0,
            );
          }
          if (rests.length) {
            timeline.fromTo(
              rests,
              { autoAlpha: 0, y: 26 },
              {
                autoAlpha: 1,
                y: 0,
                duration: 0.68,
                stagger: 0.075,
                ease: "power3.out",
              },
              masks.length ? 0.16 : 0,
            );
          }
        });

      // Counters in act 04.
      root
        .querySelectorAll<HTMLElement>("[data-count-to]")
        .forEach((node) => {
          const target = Number(node.dataset.countTo ?? "0");
          const counter = { value: 0 };
          gsap.to(counter, {
            value: target,
            duration: 1.5,
            ease: "power2.out",
            snap: { value: 1 },
            onUpdate: () => {
              node.textContent = String(counter.value);
            },
            scrollTrigger: {
              trigger: node,
              start: "top 86%",
              once: true,
            },
          });
        });
    }, root);

    const refresh = window.setTimeout(() => {
      ScrollTrigger.refresh();
      measure();
    }, 120);

    // Re-measure whenever the flow changes height — fonts landing, a phone
    // rotating. Debounced, because the track is rebuilt from live offsets
    // and a resize fires in bursts.
    let remeasure = 0;
    const observer = new ResizeObserver(() => {
      window.clearTimeout(remeasure);
      remeasure = window.setTimeout(measure, 180);
    });
    observer.observe(flow);

    return () => {
      window.clearTimeout(refresh);
      window.clearTimeout(remeasure);
      observer.disconnect();
      context.revert();
    };
  }, [prefersReducedMotion, applyPose, measure, paint]);

  /** Anchor links go through Lenis so they inherit the page's easing instead
   *  of fighting it, and reduced motion jumps instantly. */
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const onClick = (event: MouseEvent) => {
      const anchor = (event.target as HTMLElement | null)?.closest?.(
        'a[href^="#"]',
      ) as HTMLAnchorElement | null;
      if (!anchor) return;
      const id = anchor.getAttribute("href")?.slice(1);
      if (!id) return;
      const target = root.querySelector<HTMLElement>(`#${CSS.escape(id)}`);
      if (!target) return;
      event.preventDefault();
      if (prefersReducedMotion || !lenis) {
        target.scrollIntoView({
          behavior: prefersReducedMotion ? "auto" : "smooth",
          block: "start",
        });
        return;
      }
      lenis.scrollTo(target, { duration: 1.25 });
    };
    root.addEventListener("click", onClick);
    return () => root.removeEventListener("click", onClick);
  }, [lenis, prefersReducedMotion]);

  /** The door: one wipe covers the page before the router moves.
   *
   *  The fade is a class, not a tween on the root: a transform or filter on
   *  `.landing-page` would turn it into the containing block for the fixed
   *  book stage and the ambient wash, and both would jump. */
  const enterLibrary = useCallback(() => {
    if (entering) return;
    // 门帘盖上来之前先把书架那块包取上：0.86s 的擦除动画正好当下载掩护。
    prefetchHomeLobby();
    setEntering(true);
    const door = doorRef.current;
    const root = rootRef.current;
    if (!door || !root || prefersReducedMotion) {
      navigate(LIBRARY_PATH);
      return;
    }
    root.classList.add("is-entering");
    gsap.fromTo(
      door,
      { clipPath: "ellipse(0% 0% at 50% 78%)" },
      {
        clipPath: "ellipse(165% 165% at 50% 78%)",
        duration: 0.86,
        ease: "power3.inOut",
        onComplete: () => navigate(LIBRARY_PATH),
      },
    );
  }, [entering, navigate, prefersReducedMotion]);

  return (
    <div
      ref={rootRef}
      className="landing-page"
      data-tone={tone}
      data-active-act={activeAct}
      data-entering={entering ? "true" : "false"}
    >
      {/* Fixed ambient wash: staff rules, drifting notes, one soft moon. It
          sits under the book and over the act bands. */}
      <div className="landing-ambient" aria-hidden="true">
        <span className="landing-ambient__moon" />
        <div className="landing-ambient__staff">
          {Array.from({ length: 5 }, (_, index) => (
            <i key={index} className="landing-ambient__staff-line" />
          ))}
        </div>
        {["♪", "♩", "♫", "♬", "♩", "♫"].map((note, index) => (
          <span
            key={`${note}-${index}`}
            className="landing-ambient__note"
            data-note={index}
          >
            {note}
          </span>
        ))}
      </div>

      {/* The floating book. Fixed, so it stays put while the acts scroll past
          and only its pose changes. */}
      <div ref={stageRef} className="landing-stage" aria-hidden="true">
        {/* Third transform layer: GSAP owns .landing-stage, the scroll pose
            nudges --bk-dx/--bk-dy here, and rotation/scale land on
            .landing-book__body. One transform per element, so no two tweens
            ever write the same property. */}
        <div className="landing-stage__offset">
          <LandingBook />
        </div>
      </div>

      <header className="landing-nav">
        <a className="landing-nav__brand" href="#hero">
          <img src="/leafia-mark.svg" alt="" />
          <span>
            <strong>Leafia</strong>
            <small>Moonlit knowledge space</small>
          </span>
        </a>
        <nav className="landing-nav__links" aria-label="页面导航">
          {NAV_LINKS.map((link) => (
            <a key={link.id} href={`#${link.id}`}>
              {link.en}
            </a>
          ))}
        </nav>
        <div className="landing-nav__actions">
          {session ? (
            <button
              type="button"
              className="landing-account-chip"
              aria-label={`账号 ${session.user.displayName}`}
              onClick={() => setAccountOpen(true)}
            >
              <span aria-hidden="true">
                {session.user.displayName.trim().slice(0, 1).toUpperCase() ||
                  "I"}
              </span>
              <strong>{session.user.displayName}</strong>
            </button>
          ) : (
            <button
              type="button"
              className="landing-button landing-button--ghost is-compact landing-button--account"
              onClick={() => setAccountOpen(true)}
            >
              <UserRound size={14} strokeWidth={2.1} />
              登录
            </button>
          )}
          <button
            type="button"
            className="landing-button landing-button--solid is-compact"
            onClick={enterLibrary}
            onPointerEnter={prefetchHomeLobby}
            onFocus={prefetchHomeLobby}
          >
            进入知识库
          </button>
        </div>
      </header>

      <ol className="landing-rail" ref={railRef} aria-label="章节进度">
        {LANDING_ACTS.map((act) => (
          <li key={act.id} className={act.id === activeAct ? "is-active" : ""}>
            <a href={`#${act.id}`}>
              <em>{act.index}</em>
              <span>{act.label}</span>
            </a>
          </li>
        ))}
      </ol>

      <main className="landing-flow" ref={flowRef}>
        <HeroAct />
        <StoryAct />
        <CraftAct />
        <NumbersAct />
        <EnterAct onEnter={enterLibrary} />
      </main>

      {/* Door wipe. Closed (clip-path collapsed) until the reader commits. */}
      <div ref={doorRef} className="landing-door" aria-hidden="true" />

      <AuthDialog
        open={accountOpen}
        onClose={() => setAccountOpen(false)}
      />
    </div>
  );
}
